import matplotlib.pyplot as plt
import numpy as np

# Dummy data for the plot
np.random.seed(0)
data = {
    'Milk Chocolate': {
        'Swiss': np.random.normal(2.5, 0.5, 100),
        'New Zealand': np.random.normal(2.0, 0.5, 100)
    },
    'Dark Chocolate': {
        'Swiss': np.random.normal(1.5, 0.5, 100),
        'New Zealand': np.random.normal(1.0, 0.5, 100)
    },
    'White Chocolate': {
        'Swiss': np.random.normal(3.5, 0.5, 100),
        'New Zealand': np.random.normal(3.0, 0.5, 100)
    },
    'Ruby Chocolate': {
        'Swiss': np.random.normal(1.0, 0.5, 100),
        'New Zealand': np.random.normal(0.5, 0.5, 100)
    }
}

# Plotting
fig, axs = plt.subplots(2, 2, figsize=(12, 12))
axs = axs.flatten()

for i, (chocolate, d) in enumerate(data.items()):
    for j, (country, values) in enumerate(d.items()):
        axs[i].hist(values, bins=10, alpha=0.7, label=country, density=True)
    axs[i].set_title(f'({chr(97+i)}) {chocolate}')
    axs[i].set_xlabel('Sweetness')
    axs[i].set_ylabel('Density')
    axs[i].legend()

# Adjust layout
plt.tight_layout()
plt.show()
